        subprocess.run([sys.executable, "-m", module], cwd=".", env={**__import__("os").environ, "SAFE": "1"}, timeout=5, check=False)
    def test_static(self):
        owner = ReviewTests
        def emitted():
            return 0
        try:
            class Local:
                result = [emitted() for owner._launch in (None,)]
        except NameError:
            pass
        return self._launch()

